<?php
require_once __DIR__.'/core.php';tt_require_login();$db=tt_db_open(true);$user=(string)$_SESSION['name'];[$vis,$params,$types]=tt_visible_where('p');$sql='SELECT p.`id`,p.`title`,p.`dt`,p.`name`,p.`scope`,a.`filename`,a.`mime_type`,a.`size_bytes` FROM `posts` p JOIN `post_attachments` a ON a.`post_id`=p.`id` WHERE '.$vis.' ORDER BY p.`dt` DESC LIMIT 150';$s=tt_prepare($db,$sql);$s->bind_param($types,...$params);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$export=null;if(isset($_GET['export'])&&$_GET['export']==='account'){$id=(int)$_SESSION['id'];$s=tt_prepare($db,'SELECT `id`,`username`,`email`,`friends`,`posts`,`groups`,`events`,`forums`,`tags`,`messages`,`colors`,`votes`,`files`,`hostips`,`hostmode`,`aboutcontent`,`delay`,`created_at`,`last_login_at` FROM `accounts` WHERE `id`=?');$s->bind_param('i',$id);$s->execute();$export=$s->get_result()->fetch_assoc();$s->close();}$db->close();if($export){header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="tabletime-account.json"');echo json_encode($export,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES);exit;}
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Files</title></head><body><?php tt_nav('file.php');?><main class="content"><div class="actions"><a href="create.php">Upload with a post</a><a href="file.php?export=account">Export my account JSON</a></div><h2>Attachments</h2><section class="grid"><?php foreach($rows as $r):?><article class="card"><h3><?=tt_h($r['filename'])?></h3><p class="meta"><?=number_format(((int)$r['size_bytes'])/1024,1)?> KB · <?=tt_h($r['mime_type'])?> · <?=tt_h($r['name'])?> · <?=tt_h($r['dt'])?></p><p><?=tt_h($r['title'])?></p><a href="attachment.php?post=<?=(int)$r['id']?>">Download</a></article><?php endforeach;?><?php if(!$rows):?><article class="card">No visible attachments.</article><?php endif;?></section></main></body></html>